import itertools, sys
from fractions import Fraction

def pieces_from(marks):
    pts=[Fraction(0)]+sorted(set(marks))+[Fraction(1)]
    return [pts[i+1]-pts[i] for i in range(len(pts)-1)]

def liu_payoff(L,X):
    pcs=pieces_from(set(L)|set(X))
    pcs.sort(reverse=True)
    return sum(pcs[0::2])

def best_xiang(L,grid,n):
    Lset=set(L); avail=[g for g in grid if g not in Lset]
    best=None;bx=None
    for k in range(n+1):
        for X in itertools.combinations(avail,k):
            p=liu_payoff(L,X)
            if best is None or p<best: best=p;bx=X
    return best,bx

def c_brute(n,K):
    grid=[Fraction(i,K) for i in range(1,K)]
    best=None;cfg=None
    for k in range(n+1):
        for L in itertools.combinations(grid,k):
            xp,xx=best_xiang(list(L),grid,n)
            if best is None or xp>best: best=xp;cfg=(L,xx)
    return best,cfg

