import numpy as np
def liu_take(pieces):
    s=sorted(pieces,reverse=True)
    return sum(s[i] for i in range(0,len(s),2))

# Strategy A: "greedy split-largest-into-equal-halves" — repeatedly split the current largest interval in half.
def strat_split_halves(intervals, n_marks):
    P=list(intervals)
    for _ in range(n_marks):
        i=max(range(len(P)), key=lambda i: P[i])
        h=P[i]/2
