from fractions import Fraction as F
import random

ALPHA = F(1,15)

def subfam_caps(a,b,c,d, which):
    caps = {}
    if 'a' in which: caps['a']=a
    if 'b-a' in which: caps['b-a']=b-a
    if 'c-b' in which: caps['c-b']=c-b
    if 'd-c' in which: caps['d-c']=d-c
    if '|a+b-c|' in which: caps['|a+b-c|']=abs(a+b-c)
    if '|a+c-d|' in which: caps['|a+c-d|']=abs(a+c-d)
    if '|b+c-d|' in which: caps['|b+c-d|']=abs(b+c-d)
    if 'sliver' in which:
        if d >= F(1,2):
            caps['sliver']=abs(2*d-1)
        elif d > b+c:
            caps['sliver']=abs(2*d-1)  # 1-2d
        else:
            caps['sliver']=None
    return caps

def grid_test(N, which, region):
    vios=0; cnt=0; maxm=F(0); worst=None; eqs=0
    for i in range(0,N+1):
        for j in range(i,N+1-i):
            for k in range(j,N+1-i-j):
                l=N-i-j-k
                if l<k: continue
                a,b,c,d=F(i,N),F(j,N),F(k,N),F(l,N)
                if not region(a,b,c,d): continue
                cnt+=1
                caps=subfam_caps(a,b,c,d,which)
                valid=[v for v in caps.values() if v is not None]
                if not valid: continue
                m=min(valid)
                if m>ALPHA:
                    vios+=1
                    if m>maxm: maxm=m; worst=(a,b,c,d,m)
                if m==ALPHA: eqs+=1
    return vios,cnt,maxm,worst,eqs

subfamilies = [
    {'a','b-a','|a+b-c|','|b+c-d|','sliver'},
    {'a','b-a','c-b','|a+b-c|','|b+c-d|','sliver'},
    {'a','b-a','c-b','d-c','|a+b-c|','|b+c-d|','sliver'},
    {'a','b-a','c-b','|a+b-c|','|a+c-d|','|b+c-d|','sliver'},
]
